    }
  ],
  "sourceEvidence": [
    {
      "location": "PASSAGE",
      "quote": "pH가 낮은 용액에서는 수소 이온 농도가 높으므로 이온화 지질이 양이온화된다.",
      "mediaId": null,
      "visualObservation": null
